/*
 * Synthetic dual-track 3GP for the nj_mp4 audio-track tests.
 *
 * Generated by tools/gen_m4v_audio_clip.py - do not edit by hand.
 * The file is a real ISO base media container:
 *
 *   64x48 mp4v video track, 2 samples of 4 bytes, one chunk
 *   AMR-NB 'samr' sound track, 5 samples in 2 chunks (3 + 2),
 *   timescale 8000, one stts run of 160 (20 ms) per sample
 *
 * The video samples come first in 'mdat', so both tracks can be
 * selected from the same buffer and the two iterators cannot share
 * state (each nj_mp4 is its own cursor).
 *
 * Expected audio track: codec 0x73616d72, timescale 8000,
 * duration 800, 5 samples, 1 channel, 8000 Hz, first sample at
 * offset 32 size 13 dts 0 duration 160,
 * samples [13,12,15,14,16] in chunks of 3 and 2.
 *
 * The three REAL corpus movies, for reference (verified with
 * tools/mp4_audio_stats.c against ffprobe; see docs/CODECS.md):
 *   1942.3gp : 8000 Hz, timescale 8000, 109 samples of 100 ms
 *              (each holds five 32-byte AMR frames), first at 3703
 *   doom.3gp : 8000 Hz, timescale 8000, 624 samples of 20 ms
 *              (one 32-byte AMR frame each), first at 28
 *   movie.3gp: 8000 Hz, timescale 8000, 172 samples of 100 ms
 *              (each holds five 27-byte AMR frames), first at 40
 * Their ChannelCount field is 2 in two of the files even though
 * AMR-NB is mono by definition; the iterator reports what the
 * container says, and AMR callers must treat it as mono.
 */
